from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

# Load the workbook and select the sheet
wb = load_workbook("input.xlsx")
ws = wb["sheet1"]

# Define the source and target ranges
source_range = ws["A:C"]
helper_column = ws["J"]
target_range = ws["F:H"]

# Extract data from source range, skipping empty cells and headers
data = []
for row in source_range:
    if any(cell.value is None for cell in row):
        continue
    if row[0].value == "ITEM":
        continue
    data.append((row[0].value, row[1].value, row[2].value))

# Extract unique names from helper column J, skipping empty cells and headers
helper_names = set()
for cell in helper_column:
    if cell.value is None or cell.value == "LIST":
        continue
    helper_names.add(cell.value)

# Group data by (NAME, REF) to avoid duplicates
unique_data = {}
for item, name, ref in data:
    key = (name, ref)
    if key not in unique_data:
        unique_data[key] = (item, name, ref)

# Prepare the final list of data to be written to F:H
final_data = []

# First, process entries with names in the helper column
for key in unique_data:
    name, ref = key
    if name in helper_names:
        final_data.append((name, ref, unique_data[key][0]))

# Then, process entries not in the helper column
for key in unique_data:
    name, ref = key
    if name not in helper_names:
        final_data.append((name, ref, unique_data[key][0]))

# Sort the final_data by name in the helper column, then alphabetically
# If helper column is empty, sort alphabetically
if helper_names:
    # Group by name in helper column and preserve order
    grouped = {}
    for name in helper_names:
        grouped[name] = []
    for name, ref, item in final_data:
        grouped[name].append((ref, item))
    # Reconstruct final_data in the order of helper_names
    final_data = []
    for name in helper_names:
        for ref, item in grouped[name]:
            final_data.append((name, ref, item))
else:
    # Sort alphabetically by name
    final_data.sort(key=lambda x: x[0])

# Write the final_data to F:H, sorting column H lowest to highest
# First, clear the target range
for row in target_range:
    for cell in row:
        cell.value = None

# Write the data to F:H
for idx, (name, ref, item) in enumerate(final_data, start=2):
    ws[f"G{idx}"] = name
    ws[f"H{idx}"] = item

# Save the workbook
wb.save("output.xlsx")
