from openpyxl import load_workbook
from openpyxl.styles import Font, Alignment, NumberFormat
from openpyxl.utils import get_column_letter
import re

def format_cell(cell, number_format):
    cell.number_format = number_format
    if cell.value is not None:
        try:
            # Check if the value is a float and round to one decimal place
            if isinstance(cell.value, float):
                cell.value = round(cell.value, 1)
                # Format to display as per the number format
                if abs(cell.value) == int(abs(cell.value)):
                    cell.value = int(cell.value)
                else:
                    cell.value = float(cell.value)
        except:
            pass

def main():
    # Load the workbook
    wb = load_workbook("input.xlsx")
    ws = wb["Sheet1"]

    # Set Excel to automatic calculation
    ws.parent.calculate_formulas = True

    # Define the number formats
    number_format_decimal = "0.0"
    number_format_whole = "0"

    # Iterate through the rows to identify blocks
    blocks = []
    current_block = []
    for row in ws.iter_rows(min_row=1, max_col=12, values_only=False):
        if row[0].value is None:
            if current_block:
                blocks.append(current_block)
                current_block = []
        else:
            current_block.append(row)
    if current_block:
        blocks.append(current_block)

    # Process each block
    for block in blocks:
        # Extract the data for the block
        data = [row for row in block]

        # Ensure that the formulas are evaluated
        for row in data:
            for cell in row:
                if cell.value is not None and isinstance(cell.value, str) and cell.value.startswith("="):
                    # Convert formula to value
                    cell.value = cell.value

        # Format columns D, E, F
        for row in data:
            for col_idx, cell in enumerate(row):
                if col_idx in [3, 4, 5]:  # Columns D, E, F
                    # Set bold and center alignment
                    cell.font = Font(bold=True)
                    cell.alignment = Alignment(horizontal="center")
                    # Format the number
                    if isinstance(cell.value, float):
                        if abs(cell.value) == int(abs(cell.value)):
                            format_cell(cell, number_format_whole)
                        else:
                            format_cell(cell, number_format_decimal)
                    elif isinstance(cell.value, int):
                        format_cell(cell, number_format_whole)

        # Sort the block by column D in descending order
        data.sort(key=lambda x: x[3].value, reverse=True)

        # Write the sorted block back to the worksheet
        for i, row in enumerate(data):
            for j, cell in enumerate(row):
                ws.cell(row=ws.max_row - len(data) + i + 1, column=j + 1, value=cell.value)

    # Save the workbook
    wb.save("output.xlsx")

if __name__ == "__main__":
    main()
